"use client";

import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface NewVisitorModalProps {
  onClose: () => void;
  onSubmit: (visitorData: any) => void;
}

export function NewVisitorModal({ onClose, onSubmit }: NewVisitorModalProps) {
  const [formData, setFormData] = useState({
    name: "",
    purpose: "",
    date: "",
    timeSlot: "",
    relation: "",
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit(formData);
  };

  const handleInputChange = (field: string, value: string) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  return (
    <Dialog open={true} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>Schedule New Visit</DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="name">Visitor Name *</Label>
              <Input
                id="name"
                placeholder="Enter visitor's full name"
                value={formData.name}
                onChange={(e) => handleInputChange("name", e.target.value)}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="purpose">Purpose of Visit *</Label>
              <Input placeholder="Enter purpose" />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="date">Visit Date *</Label>
              <Input
                id="date"
                type="date"
                value={formData.date}
                onChange={(e) => handleInputChange("date", e.target.value)}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="timeSlot">Time Slot *</Label>
              <Select
                value={formData.timeSlot}
                onValueChange={(value) => handleInputChange("timeSlot", value)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select time slot" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="9:00 AM - 11:00 AM">
                    9:00 AM - 11:00 AM
                  </SelectItem>
                  <SelectItem value="11:00 AM - 1:00 PM">
                    11:00 AM - 1:00 PM
                  </SelectItem>
                  <SelectItem value="1:00 PM - 3:00 PM">
                    1:00 PM - 3:00 PM
                  </SelectItem>
                  <SelectItem value="3:00 PM - 5:00 PM">
                    3:00 PM - 5:00 PM
                  </SelectItem>
                  <SelectItem value="5:00 PM - 7:00 PM">
                    5:00 PM - 7:00 PM
                  </SelectItem>
                  <SelectItem value="7:00 PM - 9:00 PM">
                    7:00 PM - 9:00 PM
                  </SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <div className="space-y-2">
            <Label htmlFor="relation">Relation With Resident</Label>
            <Input
              id="relation"
              type="text"
              value={formData.relation}
              placeholder="Relation With Resident"
              onChange={(e) => handleInputChange("relation", e.target.value)}
              required
            />
          </div>

          <div className="flex gap-3 pt-4">
            <Button type="submit" className="flex-1">
              Schedule Visit
            </Button>
            <Button type="button" variant="outline" onClick={onClose}>
              Cancel
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}
